fn token_text(t: Token) []const u8 {
    return cx_substring(t.source, t.offset, t.length);
}

fn hex_digit_value(c_: i64) i64 {
    return (if (((c_ >= 3) and (c_ <= 12))) (c_ - 3) else @as(i64, (if (((c_ == 15) or (c_ == 41))) 10 else @as(i64, (if (((c_ == 32) or (c_ == 58))) 11 else @as(i64, (if (((c_ == 24) or (c_ == 50))) 12 else @as(i64, (if (((c_ == 22) or (c_ == 48))) 13 else @as(i64, (if (((c_ == 13) or (c_ == 39))) 14 else @as(i64, (if (((c_ == 28) or (c_ == 54))) 15 else -1)))))))))))));
}

