fn lit_text_to_integer(t: []const u8) i64 {
    return (if (is_hex_literal_text(t)) hex_text_value(t, 1, cx_text_len(t), 0) else dec_text_value(t, 0, cx_text_len(t), 0));
}

fn pat_lit_to_integer(t: []const u8) i64 {
    return @as(i64, (if (cx_text_eq(t, "\x28\x15\x19\x0d")) 1 else @as(i64, (if (cx_text_eq(t, "\x36\x0f\x17\x13\x0d")) 0 else lit_text_to_integer(t)))));
}

